"""Offline national static-site build for rvdumpstationsusa.com."""
from pathlib import Path
from collections import defaultdict
from html import escape as e
import json,re
from xml.etree.ElementTree import Element,SubElement,ElementTree
R=Path(__file__).resolve().parents[1];OUT=R/'docs';DOMAIN='https://rvdumpstationsusa.com';BRAND='RV Dump Stations USA'
D=json.loads((R/'data/stations.json').read_text());S=D['stations'];paths=[]
def slug(s):return re.sub('[^a-z0-9]+','-',s.lower()).strip('-')
def href(p=''):return '/'+p.strip('/')+('/' if p.strip('/') else '')
def link(p,t,current=None):return '<a href="'+href(p)+'"'+(' aria-current="page"' if current==p.strip('/') else '')+'>'+e(t)+'</a>'
def script(obj):return '<script type="application/ld+json">'+json.dumps(obj,ensure_ascii=False).replace('<','\\u003c')+'</script>'
def page(path,title,body,desc,crumbs=None,notfound=False):
 canonical=DOMAIN+('/404.html' if notfound else href(path))
 schema={'@context':'https://schema.org','@graph':[{'@type':'Organization','@id':DOMAIN+'/#organization','name':BRAND,'url':DOMAIN+'/'},{'@type':'WebSite','@id':DOMAIN+'/#website','name':BRAND,'url':DOMAIN+'/','publisher':{'@id':DOMAIN+'/#organization'}},{'@type':'WebPage','@id':canonical+'#webpage','url':canonical,'name':title,'isPartOf':{'@id':DOMAIN+'/#website'}}]}
 if crumbs:schema['@graph'].append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':DOMAIN+href(p)} for i,(p,n) in enumerate(crumbs)]})
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="'+('noindex,follow' if notfound else 'index,follow')+'"><title>'+e(title)+' | '+BRAND+'</title><meta name="description" content="'+e(desc)+'"><link rel="canonical" href="'+canonical+'"><link rel="stylesheet" href="/assets/style.css">'+script(schema)+'</head><body><a class="skip" href="#main">Skip to content</a><header>'+link('',BRAND,path)+'<nav>'+link('texas','Texas stations',path)+link('about','About & method',path)+'</nav></header><main id="main">'+body+'</main><footer><strong>Official sources. Clear unknowns.</strong><p>Independent directory · Not affiliated with listed agencies or operators · No booking or payment services.</p><p>A source check is not a live-status guarantee. Confirm access, fees and closures with the operator before you drive.</p><p>'+link('about','How we check listings')+' · Sister project: <a href="https://tossmap.com/">TossMap disposal directory</a></p></footer></body></html>'
 p=OUT/'404.html' if notfound else OUT/path/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html)
 if not notfound:paths.append(canonical)
def cards(items):
 return '<div class="cards">'+''.join('<article class="card" data-search="'+e((s['name']+' '+s['city']).lower())+'"><span class="eyebrow">'+e(s['city'])+' · TX</span><h3>'+link('texas/stations/'+s['id'],s['property_name'])+'</h3><p>Operator-listed RV dump station</p><small>Access and operating status may be restricted.</small></article>' for s in items)+'</div>'
def search():return '<label class="search">Find a station, city or lake area<input type="search" id="search" placeholder="Try Austin, Ranger or Canyon Lake"></label><p id="results" aria-live="polite">'+str(len(S))+' Texas locations shown</p><script>document.getElementById("search").addEventListener("input",function(){let n=0;document.querySelectorAll("[data-search]").forEach(c=>{c.hidden=!c.dataset.search.includes(this.value.toLowerCase());if(!c.hidden)n++});document.getElementById("results").textContent=n ? n+" locations shown" : "No matching locations. Try another station, city or lake area."})</script>'
bycity=defaultdict(list)
for s in S:bycity[s['city']].append(s)
states='Alabama|Alaska|Arizona|Arkansas|California|Colorado|Connecticut|Delaware|Florida|Georgia|Hawaii|Idaho|Illinois|Indiana|Iowa|Kansas|Kentucky|Louisiana|Maine|Maryland|Massachusetts|Michigan|Minnesota|Mississippi|Missouri|Montana|Nebraska|Nevada|New Hampshire|New Jersey|New Mexico|New York|North Carolina|North Dakota|Ohio|Oklahoma|Oregon|Pennsylvania|Rhode Island|South Carolina|South Dakota|Tennessee|Utah|Vermont|Virginia|Washington|West Virginia|Wisconsin|Wyoming'.split('|')
page('','RV dump stations in the USA','<p class="eyebrow">UNITED STATES · OFFICIAL-SOURCE DIRECTORY</p><h1>Find your next RV<br>dump stop.</h1><p class="lead">Building a nationwide directory, one verified state at a time. Texas is our first live section, with '+str(len(S))+' operator-listed locations.</p><p><a class="button" href="/texas/">Browse Texas dump stations</a></p><div class="notice"><strong>Plan before you pull in.</strong> Some stations serve campers only. Unknown does not mean free, open, potable, or available to non-guests.</div><div class="stats"><div><b>1</b>live state</div><div><b>'+str(len(S))+'</b>Texas locations</div><div><b>100%</b>official-source listings</div></div><h2>Choose a state</h2><article class="card"><h3>'+link('texas','Texas — live')+'</h3><p>State parks, USACE campgrounds and verified travel-center amenities.</p></article><details><summary>Other states — coming soon</summary><p>We do not publish empty state pages or unverified locations.</p><div class="state-grid">'+''.join('<span>'+e(s)+' — coming soon</span>' for s in states)+'</div></details>','Find official-source RV dump stations in the United States. Texas is the first live state; other states are coming soon.')
page('texas','Texas RV dump stations','<p class="eyebrow">'+link('','USA')+' / TEXAS</p><h1>Texas RV dump stations</h1><p class="lead">'+str(len(S))+' operator-listed properties. Choose a city or lake area, then check the station’s access rules and official alerts.</p><div class="notice">These are listed amenities, not guaranteed public dumping stops. Confirm the operator’s current restrictions before traveling.</div><div class="cities">'+''.join(link('texas/cities/'+slug(c),c+' ('+str(len(v))+')') for c,v in sorted(bycity.items()))+'</div>'+search()+cards(S),'Browse official-source Texas RV dump stations, including state parks, USACE campgrounds and travel centers.',[('','USA'),('texas','Texas')])
for city,items in sorted(bycity.items()):
 page('texas/cities/'+slug(city),'RV dump stations — '+city+', Texas','<p class="eyebrow">'+link('texas','TEXAS')+' / '+e(city.upper())+'</p><h1>RV dump stations — '+e(city)+', Texas</h1><p class="lead">'+str(len(items))+' operator-listed '+('property' if len(items)==1 else 'properties')+'. This is the operator’s locality or named lake area, not a radius search. Confirm each property’s station entrance and access.</p>'+cards(items),'Operator-listed RV dumping facilities in '+city+', Texas.',[('','USA'),('texas','Texas'),('texas/cities/'+slug(city),city)])
for s in S:
 qs='<dl class="questions">'+''.join('<div><dt>'+e(q)+'</dt><dd><span class="tag">'+('Documented' if s['questions'][k]['status']=='documented' else 'Not confirmed')+'</span><p>'+e(s['questions'][k]['answer'])+'</p>'+('<a href="'+e(s['questions'][k]['source_url'])+'">Official evidence ↗</a>' if s['questions'][k]['source_url'] else '')+'</dd></div>' for k,q in D['questions'].items())+'</dl>'
 sources='<ul class="sources">'+''.join('<li><a href="'+e(v['url'])+'">'+e(v['url'])+'</a>'+('<p>'+e(v['evidence'])+'</p>' if v.get('evidence') else '')+'</li>' for v in s['sources'])+'</ul>'
 alerts='<details open class="notice"><summary>Operator alerts — check before traveling</summary>'+''.join('<p>'+e(a['text'])+' <a href="'+e(a['url'])+'">Official alert ↗</a></p>' for a in s['alerts'])+'</details>' if s['alerts'] else ''
 a=s['address'];addr=', '.join(x for x in [a['street'],s['city'],'TX '+(a['postal_code'] or '')] if x)
 body='<p class="eyebrow">'+link('texas/cities/'+slug(s['city']),s['city']+', Texas')+'</p><h1>'+e(s['property_name'])+'</h1><p class="lead">RV dump station · '+e(s['operator'])+'</p><p><a class="button" href="'+e(s['operator_url'])+'">Check the official operator page ↗</a></p><div class="notice">'+e(s['verification_scope'])+'</div><section><h2>Where to go</h2><p>'+e(addr)+'</p><p>'+e(a['precision'])+'</p><p>Property status: '+e(s['park_status'])+'. This does not confirm dump-station availability.</p></section>'+alerts+'<h2>Know before you arrive</h2>'+qs+'<section><h2>Sources & verification</h2><p>Official sources last checked '+e(s['last_checked'])+'.</p>'+sources+'</section>'
 address={'@type':'PostalAddress','addressRegion':'TX','addressCountry':'US'}
 if a['street']:address.update(streetAddress=a['street'],addressLocality=s['city'],postalCode=a['postal_code'])
 canonical=DOMAIN+href('texas/stations/'+s['id'])
 body+=script({'@context':'https://schema.org','@type':'Place','@id':canonical+'#place','url':canonical,'name':s['name'],'address':address,'description':s['verification_scope'],'additionalProperty':[{'@type':'PropertyValue','name':'Official-source last checked','value':s['last_checked']}]})
 page('texas/stations/'+s['id'],s['name'],body,'Official sources and RV dumping questions for '+s['property_name']+'.',[('','USA'),('texas','Texas'),('texas/cities/'+slug(s['city']),s['city']),('texas/stations/'+s['id'],s['property_name'])])
page('about','About and verification methodology','<p class="eyebrow">ABOUT RV DUMP STATIONS USA</p><h1>Sources, not assumptions.</h1><p class="lead">An independent national directory starting with Texas. We help RV travelers find operator-listed waste-disposal facilities and see what is—and is not—confirmed.</p><h2>What we verify</h2><p>Every property must have location-specific evidence from its official operator or government agency explicitly listing a dump station. Texas state parks come from TPWD’s public amenity records, supplemented by park pages and alerts. USACE campground listings use the agency’s park descriptions. Travel centers use the operator’s location-specific amenities and addresses.</p><h2>What we do not assume</h2><p>We have not inspected these sites. A listed amenity does not establish live service, non-guest access, potable water, payment methods or large-rig clearance. Store, park or office hours are not dump-station hours. Campsite length limits and water/sewer hookups are not proof of dump-station access or a potable fill. Unconfirmed facts stay unknown.</p><h2>Locations and counting</h2><p>One listing per property, not per dump lane. Where a USACE source identifies the lake but no verified street address, we show a named lake area and link directly to operator directions; we never reuse the project-office address as the campground address. Cities and lake areas are browse groups, not radius searches. We do not claim a comprehensive inventory.</p><h2>Closures and updates</h2><p>Official alerts and restrictions are displayed on station pages. A last-checked date records a source review, not an on-site inspection or confirmation of service today. Review the operator page before traveling.</p><h2>Independence and sister project</h2><p>RV Dump Stations USA is a sister project to <a href="https://tossmap.com/">TossMap, the disposal and recycling directory</a>. We are not affiliated with listed agencies or operators. There are no paid placements, sponsors or affiliate arrangements. Any future featured placements would be clearly labeled and would not alter factual verification.</p><h2>Coverage</h2><p>Texas is the first published state. Other states are marked coming soon without empty landing pages. We do not scrape Google Maps or copy third-party directory listings.</p>','Learn how RV Dump Stations USA verifies official-source listings, handles unknown facts and reports coverage limitations.')
page('404','Page not found','<p class="eyebrow">404</p><h1>This stop is not on our map.</h1><p>The page could not be found. Texas is our first live state.</p><p><a class="button" href="/texas/">Browse Texas stations</a></p><p>'+link('','Return to the US homepage')+'</p>','Page not found. Browse the current Texas RV dump station directory.',notfound=True)
(OUT/'assets').mkdir(exist_ok=True);(OUT/'assets/style.css').write_text((R/'scripts/site.css').read_text())
(OUT/'CNAME').write_text('rvdumpstationsusa.com\n');(OUT/'.nojekyll').write_text('')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\n\nSitemap: '+DOMAIN+'/sitemap.xml\n')
root=Element('urlset',xmlns='http://www.sitemaps.org/schemas/sitemap/0.9')
for u in sorted(paths):SubElement(SubElement(root,'url'),'loc').text=u
ElementTree(root).write(OUT/'sitemap.xml',encoding='utf-8',xml_declaration=True)
print(f'Built {len(paths)+1} HTML pages ({len(paths)} indexable + 404); {len(S)} locations; {len(bycity)} city/area groups.')
